1	/**
2	 * `buildTokens` — the first and only source transformation. Reads
3	 * `@instructure/instructure-design-tokens` + `@instructure/ui-icons` and produces the canonical
4	 * `@property`-aligned {@link Token} IR (icons rolled in), then runs plugin token hooks over it.
5	 *
6	 * @module
7	 */
8	import { themeTokens } from "@instructure/instructure-design-tokens";
9	import { applyModify } from "./color.ts";
10	import { collectIcons } from "./icons.ts";
11	import { defineToken, runIconPlugins, runTokenPlugins } from "./plugin.ts";
12	import { collectLeaves, resolveValue, varName } from "./resolve.ts";
13	import type { PantokenPlugin } from "./plugin.ts";
14	import type { Leaf } from "./resolve.ts";
15	import type { Theme, Token, TokenMeta } from "./model.ts";
16	
17	/** Options for {@link buildTokens}. */
18	export interface BuildTokensOptions {
19	  /** The theme to resolve (default: `"rebrand"`). */
20	  theme?: Theme;
21	  /** Plugins whose `tokens` hooks run over the IR (default: none). */
22	  plugins?: readonly PantokenPlugin[];
23	  /** Include the icon layer (default: true). */
24	  includeIcons?: boolean;
25	  /** Include Instructure-authored (Custom) glyphs (default: true). */
26	  includeInstui?: boolean;
27	  /** Include Lucide glyphs (default: true). */
28	  includeLucide?: boolean;
29	}
30	
31	interface ThemeSpec {
32	  group: "rebrand" | "canvas";
33	  light: string;
34	  dark?: string;
35	}
36	
37	const THEME_SPECS: Record<Theme, ThemeSpec> = {
38	  rebrand: { group: "rebrand", light: "rebrandLight", dark: "rebrandDark" },
39	  canvas: { group: "canvas", light: "canvas" },
40	  canvasHighContrast: { group: "canvas", light: "canvasHighContrast" },
41	};
42	
43	/** Resolve a leaf's value, applying a concrete colour modifier or preserving it as metadata. */
44	function resolveLeaf(leaf: Leaf): { value: string; meta?: TokenMeta } {
45	  const value = resolveValue(leaf.value);
46	  if (!leaf.modify) return { value };
47	  const applied = value.startsWith("#") ? applyModify(value, leaf.modify) : undefined;
48	  return applied ? { value: applied } : { value, meta: { modify: leaf.modify } };
49	}
50	
51	function toToken(name: string, value: string, meta?: TokenMeta): Token {
52	  return defineToken({ name, value, meta });
53	}
54	
55	/**
56	 * Build the canonical token IR for a theme.
57	 *
58	 * @param options - {@link BuildTokensOptions}.
59	 * @returns The resolved, de-duplicated {@link Token} list.
60	 *
61	 * @example Build the default (rebrand) IR
62	 * ```ts
63	 * import { buildTokens } from "@pantoken/core";
64	 *
65	 * const tokens = buildTokens();
66	 * // → Token[] : { name, syntax, inherits, value, themed?, refersTo?, meta? }
67	 * ```
68	 *
69	 * @example Pick a theme and drop the icon layer
70	 * ```ts
71	 * import { buildTokens } from "@pantoken/core";
72	 *
73	 * // A smaller, colour/layout-only IR for the canvas theme.
74	 * const tokens = buildTokens({ theme: "canvas", includeIcons: false });
75	 * ```
76	 *
77	 * @example Run a plugin's tokens hook over the IR
78	 * ```ts
79	 * import { buildTokens, type PantokenPlugin } from "@pantoken/core";
80	 *
81	 * const brand: PantokenPlugin = {
82	 *   name: "brand",
83	 *   tokens: ({ tokens, define }) => [
84	 *     ...tokens,
85	 *     define({ name: "--instui-focus-color", value: "var(--instui-color-border-brand)" }),
86	 *   ],
87	 * };
88	 *
89	 * buildTokens({ theme: "rebrand", plugins: [brand] });
90	 * ```
91	 */
92	export function buildTokens(options: BuildTokensOptions = {}): Token[] {
93	  const {
94	    theme = "rebrand",
95	    plugins = [],
96	    includeIcons = true,
97	    includeInstui = true,
98	    includeLucide = true,
99	  } = options;
100	
101	  const spec = THEME_SPECS[theme];
102	  const root = themeTokens as unknown as Record<string, any>;
103	  const group = root[spec.group];
104	  const tokens: Token[] = [];
105	
106	  // 1. Primitives — shared across themes, concrete values.
107	  for (const leaf of collectLeaves(root.primitives?.default)) {
108	    const { value, meta } = resolveLeaf(leaf);
109	    tokens.push(toToken(varName("primitive", leaf.path), value, meta));
110	  }
111	
112	  // 2. Layout (size, spacing, radii, type…) — references point at primitives.
113	  for (const leaf of collectLeaves(group?.semantic?.layout?.default?.semantic)) {
114	    const { value, meta } = resolveLeaf(leaf);
115	    tokens.push(toToken(varName("", leaf.path), value, meta));
116	  }
117	
118	  // 3. Semantic colours — emit a single value when light and dark resolve identically, else wrap
119	  //    both in light-dark(). This is the only layer that produces light-dark().
120	  const darkByPath = new Map<string, Leaf>();
121	  if (spec.dark) {
122	    for (const leaf of collectLeaves(group?.semantic?.color?.[spec.dark]?.semantic)) {
123	      darkByPath.set(leaf.path.join("."), leaf);
124	    }
125	  }
126	  for (const leaf of collectLeaves(group?.semantic?.color?.[spec.light]?.semantic)) {
127	    const light = resolveLeaf(leaf);
128	    const darkLeaf = darkByPath.get(leaf.path.join("."));
129	    const dark = darkLeaf ? resolveLeaf(darkLeaf) : light;
130	    const value =
131	      light.value === dark.value ? light.value : `light-dark(${light.value}, ${dark.value})`;
132	    tokens.push(toToken(varName("", leaf.path), value, light.meta));
133	  }
134	
135	  // 4. Components — reference the colour/layout layers, so theming flows through automatically.
136	  for (const component of Object.values(group?.component ?? {})) {
137	    for (const leaf of collectLeaves(component)) {
138	      const { value, meta } = resolveLeaf(leaf);
139	      tokens.push(toToken(varName("component", leaf.path), value, meta));
140	    }
141	  }
142	
143	  // 5. Icons — rolled in as <image> tokens, plus the icon-colour special values.
144	  if (includeIcons) {
145	    const { glyphs, colors } = collectIcons({ includeInstui, includeLucide });
146	    for (const glyph of glyphs) {
147	      tokens.push(defineToken({ name: glyph.name, value: glyph.value, meta: glyph.meta }));
148	    }
149	    for (const [name, value] of colors) tokens.push(toToken(name, value));
150	  }
151	
152	  // 6. Plugin icon hooks — register extra glyphs as <image> tokens, then token hooks — both guarded
153	  //    (a wrong-stage plugin warns rather than silently doing nothing); result de-duped (later wins).
154	  const withIcons = runIconPlugins(tokens, plugins);
155	  return runTokenPlugins(withIcons, theme, plugins);
156	}
