1	/**
2	 * Build-time generator for `@pantoken/tokens`. Resolves the IR for every theme and vendors it —
3	 * plus the raw Tokens Studio JSON and upstream provenance — as static JSON under `generated`.
4	 * This is what lets the published package ship with no dependency on the (GitHub-only) upstream.
5	 */
6	import { createRequire } from "node:module";
7	import { dirname, join, resolve } from "node:path";
8	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
9	import { buildTokens } from "@pantoken/core";
10	import { themeTokens } from "@instructure/instructure-design-tokens";
11	import type { Theme } from "@pantoken/model";
12	
13	const require = createRequire(import.meta.url);
14	const outDir = resolve(import.meta.dirname, "../generated");
15	mkdirSync(outDir, { recursive: true });
16	
17	const THEMES: Theme[] = ["rebrand", "canvas", "canvasHighContrast"];
18	
19	for (const theme of THEMES) {
20	  const tokens = buildTokens({ theme });
21	  writeFileSync(join(outDir, `${theme}.json`), `${JSON.stringify(tokens)}\n`);
22	  console.log(`✓ ${theme}: ${tokens.length} tokens`);
23	}
24	
25	// Raw Tokens Studio JSON, re-published verbatim (npm + semver access without GitHub pinning).
26	writeFileSync(join(outDir, "raw.json"), `${JSON.stringify(themeTokens)}\n`);
27	
28	// Provenance: the exact upstream version this build was vendored from.
29	let upstreamVersion = "unknown";
30	try {
31	  const main = require.resolve("@instructure/instructure-design-tokens");
32	  const pkg = JSON.parse(readFileSync(join(dirname(main), "..", "package.json"), "utf8"));
33	  upstreamVersion = pkg.version ?? "unknown";
34	} catch {
35	  // Provenance is best-effort.
36	}
37	writeFileSync(
38	  join(outDir, "meta.json"),
39	  `${JSON.stringify({ upstream: "@instructure/instructure-design-tokens", upstreamVersion })}\n`,
40	);
41	console.log(`✓ raw.json + meta.json (upstream ${upstreamVersion})`);
