1	/**
2	 * `@pantoken/model` — the zero-dependency type contracts for the pantoken token IR.
3	 *
4	 * A {@link Token} is aligned to the CSS `@property` schema (`name`/`syntax`/`inherits`/
5	 * initial-`value`) and extended into a superset that also carries themed and reference values,
6	 * plus non-value {@link TokenMeta} (icons, provenance). Icons are rolled in as `<image>` tokens.
7	 * Every pantoken package depends on this package for the type, so no consumer needs the
8	 * (GitHub-only) upstream token package just to type the IR.
9	 *
10	 * @module
11	 * @beta
12	 */
13	
14	/** A colour theme available in `@instructure/instructure-design-tokens`. */
15	export type Theme = "rebrand" | "canvas" | "canvasHighContrast";
16	
17	/** A Tokens Studio colour modifier (`$extensions."studio.tokens".modify`). */
18	export interface TokenModify {
19	  /** The modification applied to the resolved colour. */
20	  type: "darken" | "lighten" | "alpha" | "mix";
21	  /** The modifier amount, `0`–`1`. */
22	  value: number;
23	  /** The colour space the modifier operates in (e.g. `"hsl"`). */
24	  space?: string;
25	  /** The second colour, for `mix`. */
26	  color?: string;
27	}
28	
29	/** Non-value metadata attached to a {@link Token}. */
30	export interface TokenMeta {
31	  /** Marks an icon token (its `syntax` is `"<image>"`). */
32	  kind?: "icon";
33	  /** The source style of an icon glyph. */
34	  style?: "Custom" | "Line" | "Solid";
35	  /** The SVG `viewBox` of an icon glyph. */
36	  viewBox?: string;
37	  /** Whether an icon flips horizontally in right-to-left contexts. */
38	  bidirectional?: boolean;
39	  /** The origin of an icon glyph. */
40	  source?: "custom" | "lucide";
41	  /** A colour modifier preserved for the native lineage (Style Dictionary). */
42	  modify?: TokenModify;
43	}
44	
45	/**
46	 * A single design token in the canonical `@property`-aligned IR.
47	 *
48	 * @property name - The custom-property name, e.g. `--instui-color-background-base`.
49	 * @property syntax - The `@property` `syntax` descriptor (`"<color>"`, `"<length>"`,
50	 *   `"<image>"`, …) or `"*"` for contextual values.
51	 * @property inherits - The `@property` `inherits` flag.
52	 * @property value - A concrete value, a `var(...)` reference, or a `light-dark(a, b)` pair.
53	 */
54	export interface Token {
55	  name: string;
56	  syntax: string;
57	  inherits: boolean;
58	  value: string;
59	  /** True when the light and dark resolutions differ (value is a `light-dark()`). */
60	  themed?: boolean;
61	  /** The token this one references, when `value` is a single `var(...)`. */
62	  refersTo?: string;
63	  /** Non-value metadata. */
64	  meta?: TokenMeta;
65	}
66	
67	/** The shape accepted by the `define()` helper; `inherits` defaults to `true`. */
68	export interface TokenInput {
69	  name: string;
70	  value: string;
71	  syntax?: string;
72	  inherits?: boolean;
73	  themed?: boolean;
74	  refersTo?: string;
75	  meta?: TokenMeta;
76	}
77	
78	// ── Plugin contract ──────────────────────────────────────────────────────────────────────────
79	// The uniform pantoken plugin type. One plugin carries optional per-stage hooks; each stage runner
80	// applies only the hooks relevant to it, so the same plugin can inject at more than one layer.
81	
82	/** A resolved icon, as returned by an {@link IconResolver}. */
83	export interface IconEntry {
84	  /** The icon name / code. */
85	  name: string;
86	  /** Inline SVG markup, when available. */
87	  svg?: string;
88	  /** SVG path data, for single-path brand icons. */
89	  path?: string;
90	  /** The SVG `viewBox` (default `"0 0 24 24"`). */
91	  viewBox?: string;
92	  /** The provider that produced this entry. */
93	  source?: string;
94	}
95	
96	/** Maps an icon code to an {@link IconEntry}, or `undefined` when it has no match. */
97	export type IconResolver = (code: string) => IconEntry | undefined;
98	
99	/** A typed `@property` registration. */
100	export interface PropertyRule {
101	  name: string;
102	  syntax: string;
103	  value: string;
104	}
105	
106	/** A CSS contribution a plugin can return from its `css` hook. */
107	export interface CssContribution {
108	  /** Raw CSS emitted before the generated base. */
109	  prepend?: string;
110	  /** Raw CSS emitted after the generated base. */
111	  append?: string;
112	  /** Typed `@property` registrations to add. */
113	  properties?: PropertyRule[];
114	  /** Scoped `--var: value` declarations to add. */
115	  declarations?: [string, string][];
116	  /** A `data-*` marker for the emitted block, for debugging. */
117	  marker?: string;
118	}
119	
120	/** Context passed to a plugin's `tokens` hook. */
121	export interface TokenHookContext {
122	  tokens: Token[];
123	  theme: Theme;
124	  define: (input: TokenInput) => Token;
125	}
126	
127	/** Context passed to a plugin's `icons` hook. */
128	export interface IconHookContext {
129	  add: (entry: IconEntry) => void;
130	  resolve: IconResolver;
131	}
132	
133	/** Context passed to a plugin's `css` hook. */
134	export interface CssHookContext {
135	  tokens: Token[];
136	  css: string;
137	}
138	
139	/** Context passed to a plugin's `rehype` hook. */
140	export interface RehypeHookContext {
141	  resolve: IconResolver;
142	}
143	
144	/**
145	 * A pantoken plugin. Every hook is optional; a plugin participates only in the stages it defines a
146	 * hook for. The same plugin can therefore inject at more than one layer.
147	 */
148	export interface PantokenPlugin {
149	  /** A unique, human-readable plugin name. */
150	  name: string;
151	  /** Token stage: return the full replacement token list (use `ctx.define` to add). */
152	  tokens?(ctx: TokenHookContext): Token[] | void;
153	  /** Icon stage: register providers via `ctx.add`, or wrap `ctx.resolve`. */
154	  icons?(ctx: IconHookContext): void;
155	  /** CSS stage: contribute or post-process CSS. */
156	  css?(ctx: CssHookContext): CssContribution | void;
157	  /** Rehype stage: provide a resolver merged into the rehype plugin. */
158	  rehype?(ctx: RehypeHookContext): { resolve?: IconResolver } | void;
159	  /** Native stage (Style Dictionary): register transforms/formats. */
160	  native?(ctx: unknown): void;
161	}
