1	/**
2	 * Validate pantoken's generated output. Run after the workspace is built (`vp run -r build`), so
3	 * every package's `generate`/`embed` step has already written its `generated/` dir. This is the
4	 * pantoken analog of a `validateTokens` drift gate: it fails if any generator produced nothing, if
5	 * the `pantoken` CLI can't emit a supported target, if a generated stylesheet references an
6	 * `--instui-*` token the IR doesn't define, or if a published CSS export bypasses the finalized
7	 * `dist/` output from `@tsdown/css`.
8	 *
9	 * @module
10	 * @beta
11	 */
12	import { execFileSync } from "node:child_process";
13	import { existsSync, mkdtempSync, readFileSync, readdirSync } from "node:fs";
14	import { tmpdir } from "node:os";
15	import { join, resolve } from "node:path";
16	import { tokens } from "@pantoken/tokens";
17	import { danglingReferences, unknownReferences } from "@pantoken/utils";
18	import { matchWildcardFiles } from "./match-wildcard.ts";
19	
20	const root = resolve(import.meta.dirname, "../..");
21	const failures: string[] = [];
22	function fail(msg: string): void {
23	  failures.push(msg);
24	  console.error(`✗ ${msg}`);
25	}
26	function ok(msg: string): void {
27	  console.log(`✓ ${msg}`);
28	}
29	
30	/** Count files recursively under a directory; 0 if it doesn't exist. */
31	function fileCount(dir: string): number {
32	  if (!existsSync(dir)) return 0;
33	  let n = 0;
34	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
35	    if (entry.isDirectory()) n += fileCount(join(dir, entry.name));
36	    else n++;
37	  }
38	  return n;
39	}
40	
41	/** List files recursively under a directory; returns workspace-relative segments (not absolute paths). */
42	function listFiles(dir: string, base = dir): string[] {
43	  if (!existsSync(dir)) return [];
44	  const files: string[] = [];
45	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
46	    const abs = join(dir, entry.name);
47	    if (entry.isDirectory()) {
48	      files.push(...listFiles(abs, base));
49	      continue;
50	    }
51	    files.push(abs.slice(base.length + 1).replaceAll("\\", "/"));
52	  }
53	  return files;
54	}
55	
56	// 1. Every generator package must have written a non-empty `generated/` dir.
57	const GENERATOR_PKGS = [
58	  "formats/css",
59	  "formats/scss",
60	  "formats/less",
61	  "formats/stylus",
62	  "formats/tokens",
63	  "formats/dtcg",
64	  "platforms/wordpress",
65	  "platforms/vanilla",
66	  "renderers/pendo",
67	  "renderers/bootstrap",
68	  "renderers/shadcn",
69	  "renderers/foundation",
70	  "renderers/docusaurus",
71	  "renderers/vitepress",
72	  "ai/pantoken-ai",
73	  "plugins/pantoken/primitives",
74	  "plugins/pantoken/stacking",
75	  "plugins/pantoken/transition",
76	  "plugins/pantoken/visual-debug",
77	];
78	for (const pkg of GENERATOR_PKGS) {
79	  const count = fileCount(join(root, pkg, "generated"));
80	  if (count === 0) fail(`${pkg}: generated/ is missing or empty (run its build)`);
81	  else ok(`${pkg}: generated/ has ${count} file(s)`);
82	}
83	
84	// 2. Every published CSS export must point at a non-empty, finalized dist file.
85	const FINALIZED_CSS_PKGS = [
86	  "formats/components",
87	  "formats/css",
88	  "plugins/pantoken/logos",
89	  "plugins/pantoken/primitives",
90	  "plugins/pantoken/stacking",
91	  "plugins/pantoken/transition",
92	  "plugins/pantoken/visual-debug",
93	  "renderers/angular",
94	  "renderers/astro",
95	  "renderers/bootstrap",
96	  "renderers/css-in-js",
97	  "renderers/docusaurus",
98	  "renderers/foundation",
99	  "renderers/mui",
100	  "renderers/pendo",
101	  "renderers/react",
102	  "renderers/shadcn",
103	  "renderers/storybook",
104	  "renderers/svelte",
105	  "renderers/vitepress",
106	  "renderers/vue",
107	  "renderers/web-components",
108	] as const;
109	for (const pkg of FINALIZED_CSS_PKGS) {
110	  const manifest = JSON.parse(readFileSync(join(root, pkg, "package.json"), "utf8")) as {
111	    exports?: Record<string, string>;
112	  };
113	  const cssExports = Object.entries(manifest.exports ?? {}).filter(([key]) => key.endsWith(".css"));
114	  if (cssExports.length === 0) {
115	    fail(`${pkg}: no CSS exports found`);
116	    continue;
117	  }
118	  for (const [key, target] of cssExports) {
119	    if (!target.startsWith("./dist/") || !target.endsWith(".css")) {
120	      fail(`${pkg}: ${key} bypasses finalized dist CSS (${target})`);
121	      continue;
122	    }
123	    if (target.includes("*")) {
124	      const rel = target.slice("./dist/".length);
125	      const distDir = join(root, pkg, "dist");
126	      const matches = matchWildcardFiles(listFiles(distDir), rel);
127	      const nonEmpty = matches.filter((file) => readFileSync(join(distDir, file)).byteLength > 0);
128	      if (nonEmpty.length === 0) {
129	        fail(`${pkg}: ${key} finalized output is missing or empty (${target})`);
130	      } else {
131	        ok(`${pkg}: ${key} resolves to ${nonEmpty.length} finalized file(s) via ${target}`);
132	      }
133	      continue;
134	    }
135	    const file = join(root, pkg, target);
136	    if (!existsSync(file) || readFileSync(file).byteLength === 0) {
137	      fail(`${pkg}: ${key} finalized output is missing or empty (${target})`);
138	    } else {
139	      ok(`${pkg}: ${key} resolves to finalized ${target}`);
140	    }
141	  }
142	}
143	
144	// The readable components sheet remains the cssdoc provider; only the published copy is minified.
145	const componentSource = readFileSync(
146	  join(root, "formats/components/generated/components.css"),
147	  "utf8",
148	);
149	const componentFinal = readFileSync(join(root, "formats/components/dist/components.css"), "utf8");
150	if (!componentSource.includes("/**")) fail("components: generated CSS lost cssdoc comments");
151	else ok("components: generated CSS retains cssdoc comments");
152	if (componentFinal.includes("/**")) fail("components: finalized CSS retained cssdoc comments");
153	else ok("components: finalized CSS strips cssdoc comments");
154	
155	// 3. The `pantoken` CLI must emit at least one file for every supported target.
156	const CLI_TARGETS = [
157	  "swift",
158	  "android",
159	  "compose",
160	  "flutter",
161	  "wordpress",
162	  "vanilla",
163	  "drupal",
164	  "swatches",
165	  "rust",
166	  "icon-font",
167	  "pendo",
168	  "jekyll",
169	  "hugo",
170	];
171	const cliBin = join(root, "packages/cli/bin/pantoken.mjs");
172	const cliTmp = mkdtempSync(join(tmpdir(), "pantoken-validate-"));
173	for (const target of CLI_TARGETS) {
174	  const out = join(cliTmp, target);
175	  try {
176	    const argv = ["generate", target, "--out", out, "--icons", "arrow-left,check-mark"];
177	    execFileSync("node", [cliBin, ...argv], { stdio: "pipe" });
178	    const count = fileCount(out);
179	    if (count === 0) fail(`cli generate ${target}: wrote no files`);
180	    else ok(`cli generate ${target}: wrote ${count} file(s)`);
181	  } catch (error) {
182	    fail(`cli generate ${target}: ${error instanceof Error ? error.message : String(error)}`);
183	  }
184	}
185	
186	// 4. Reference integrity: neither generated nor finalized stylesheets may drift from the token IR.
187	const readGenerated = (pkg: string, file: string): string =>
188	  readFileSync(join(root, pkg, "generated", file), "utf8");
189	const readFinalized = (pkg: string, file: string): string =>
190	  readFileSync(join(root, pkg, "dist", file), "utf8");
191	
192	// Self-contained sheets define what they reference — nothing should dangle.
193	const SELF_CONTAINED = [
194	  ["formats/css", "style.css"],
195	  ["renderers/pendo", "global.css"],
196	  // stacking/transition define their own `--instui-stacking-*`/`--instui-transition-*` tokens in the
197	  // sheet's `:root` and reference only those, so nothing should dangle. (visual-debug is excluded — its
198	  // outline colour is a `--pantoken-visual-debug-color` var with an inline fallback, defined nowhere.)
199	  ["plugins/pantoken/stacking", "stacking.css"],
200	  ["plugins/pantoken/transition", "transition.css"],
201	] as const;
202	for (const [pkg, file] of SELF_CONTAINED) {
203	  for (const [stage, css] of [
204	    ["generated", readGenerated(pkg, file)],
205	    ["finalized", readFinalized(pkg, file)],
206	  ] as const) {
207	    const dangling = danglingReferences(css);
208	    if (dangling.length) {
209	      fail(`${pkg}/${file} (${stage}): dangling var() refs ${dangling.join(", ")}`);
210	    } else ok(`${pkg}/${file} (${stage}): no dangling references`);
211	  }
212	}
213	
214	// Bridges only reference tokens defined elsewhere — every target must be a real token.
215	const BRIDGES = [
216	  ["renderers/bootstrap", "theme.css"],
217	  ["renderers/shadcn", "theme.css"],
218	  ["renderers/foundation", "theme.css"],
219	  ["renderers/foundation", "_settings.scss"],
220	  ["renderers/docusaurus", "custom.css"],
221	  ["renderers/vitepress", "custom.css"],
222	  // The primitive utilities only ever reference real `--instui-primitive-*` tokens.
223	  ["plugins/pantoken/primitives", "primitives.css"],
224	] as const;
225	for (const [pkg, file] of BRIDGES) {
226	  const stages = file.endsWith(".css")
227	    ? ([
228	        ["generated", readGenerated(pkg, file)],
229	        ["finalized", readFinalized(pkg, file)],
230	      ] as const)
231	    : ([["generated", readGenerated(pkg, file)]] as const);
232	  for (const [stage, css] of stages) {
233	    const unknown = unknownReferences(css, tokens);
234	    if (unknown.length) {
235	      fail(`${pkg}/${file} (${stage}): references unknown tokens ${unknown.join(", ")}`);
236	    } else ok(`${pkg}/${file} (${stage}): all token references resolve`);
237	  }
238	}
239	
240	if (failures.length) {
241	  console.error(`\n✗ validate-generated: ${failures.length} failure(s)`);
242	  process.exit(1);
243	}
244	console.log("\n✓ validate-generated: all checks passed");
