1	/**
2	 * `@pantoken/plugin-stacking` — named z-index depths.
3	 *
4	 * InstUI's `View` exposes a stacking scale (`deepest`, `below`, `above`, `topmost`) so layers stack
5	 * predictably instead of by hand-tuned magic numbers. This plugin surfaces that scale two ways: it
6	 * emits `--instui-stacking-<level>` tokens (resolved to concrete z-index values from the shipped
7	 * `--instui-component-view-stacking-*` tokens), and a matching set of `.instui-stack-<level>` utility
8	 * classes.
9	 *
10	 * Both hooks are defined, so the consumer chooses the layer: add it to `buildTokens` to bake the
11	 * `--instui-stacking-*` records into every output, or to `toCss` (the css hook self-defines them, so
12	 * the `.instui-stack-*` classes stand alone).
13	 *
14	 * @example
15	 * ```ts
16	 * import { toCss } from "@pantoken/css";
17	 * import { byTheme } from "@pantoken/tokens";
18	 * import { stacking } from "@pantoken/plugin-stacking";
19	 *
20	 * const css = toCss(byTheme("rebrand"), { plugins: [stacking()] });
21	 * // :root { --instui-stacking-topmost: … } + .instui-stack-topmost { z-index: … }
22	 * ```
23	 *
24	 * @module
25	 * @beta
26	 */
27	import { definePlugin, makeResolver } from "@pantoken/plugin-kit";
28	import { byTheme } from "@pantoken/tokens";
29	import type { PantokenPlugin, Theme, Token, TokenInput } from "@pantoken/model";
30	
31	/** The stacking depths, deepest → topmost, from InstUI's view stacking scale. */
32	export const STACKING_LEVELS: readonly string[] = ["deepest", "below", "above", "topmost"];
33	
34	/** The `.instui-stack-<level>` utility rules (prefix-fixed at `instui`, one per {@link STACKING_LEVELS}). */
35	export const STACKING_RULES: string = STACKING_LEVELS.map(
36	  (level) => `.instui-stack-${level} { z-index: var(--instui-stacking-${level}); }`,
37	).join("\n");
38	
39	/** The `--instui-stacking-<level>` name/value pairs, resolved from the view stacking scale for `theme`. */
40	function definitions(tokens: readonly Token[], theme: Theme): TokenInput[] {
41	  const resolve = makeResolver(byTheme(theme), { overrides: tokens });
42	  return STACKING_LEVELS.map((level) => ({
43	    name: `--instui-stacking-${level}`,
44	    value: resolve(`var(--instui-component-view-stacking-${level})`),
45	  }));
46	}
47	
48	/**
49	 * The `:root { --instui-stacking-*: … }` token block for the standalone `stacking.css` sheet — values
50	 * resolved to concrete z-indexes for `theme`.
51	 *
52	 * @param theme - The theme whose IR seeds resolution (default `"rebrand"`).
53	 * @returns The `:root { … }` CSS string (no doc comment, no rules).
54	 */
55	export function stackingRootCss(theme: Theme = "rebrand"): string {
56	  const decls = definitions([], theme)
57	    .map((d) => `  ${d.name}: ${d.value};`)
58	    .join("\n");
59	  return `:root {\n${decls}\n}`;
60	}
61	
62	/** Options for the {@link stacking} plugin. */
63	export interface StackingOptions {
64	  /** The theme whose shipped IR seeds reference resolution (default `"rebrand"` in the css hook). */
65	  theme?: Theme;
66	  /** Where the css-hook rules land relative to the stylesheet: `"append"` (default) or `"prepend"`. */
67	  position?: "append" | "prepend";
68	}
69	
70	/**
71	 * Create the stacking plugin.
72	 *
73	 * @param options - {@link StackingOptions}.
74	 * @returns A {@link PantokenPlugin} with `tokens` and `css` hooks.
75	 */
76	export function stacking(options: StackingOptions = {}): PantokenPlugin {
77	  const position = options.position ?? "append";
78	
79	  return definePlugin({
80	    name: "@pantoken/plugin-stacking",
81	    tokens: ({ tokens, theme, define }) => [
82	      ...tokens,
83	      ...definitions(tokens, options.theme ?? theme).map((d) => define(d)),
84	    ],
85	    css: ({ tokens }) => {
86	      const present = new Set(tokens.map((t) => t.name));
87	      const declarations = definitions(tokens, options.theme ?? "rebrand")
88	        .filter((d) => !present.has(d.name))
89	        .map((d): [string, string] => [d.name, d.value]);
90	      return {
91	        marker: "pantoken:stacking",
92	        ...(declarations.length ? { declarations } : {}),
93	        [position]: STACKING_RULES,
94	      };
95	    },
96	  });
97	}
98	
99	export default stacking;
