1	/**
2	 * Emit `generated/stacking.css` — the `:root` `--instui-stacking-*` token block, a typed `@property`
3	 * registration per token (so each carries a `<integer>` syntax and a concrete `initial-value` default,
4	 * which the cssdoc CSS-API table reads into its Type and Default columns), the authored cssdoc
5	 * `@utility` record, and the `.instui-stack-<level>` utility rules, at the default `instui` prefix. The
6	 * `:root` block leads so the doc comment binds to the first class rule (cssdoc attaches a comment to the
7	 * next rule); the `@property` at-rules trail the doc so cssdoc folds their type/default into the record.
8	 * The sheet feeds the stylelint/eslint cssdoc lint and the docs CSS-API pages.
9	 */
10	import { mkdirSync, writeFileSync } from "node:fs";
11	import { join, resolve } from "node:path";
12	import { STACKING_LEVELS, STACKING_RULES, stackingRootCss } from "../src/index.ts";
13	
14	const rootCss = stackingRootCss();
15	
16	// The concrete z-index each `--instui-stacking-<level>` resolves to, pulled from the `:root` block, so
17	// the `@property` defaults below stay in lock-step with the emitted token values.
18	const valueByName = new Map(
19	  [...rootCss.matchAll(/(--instui-stacking-[\w-]+):\s*(-?\d+);/gu)].map((m) => [m[1], m[2]]),
20	);
21	
22	// One typed registration per token: `z-index` is an integer, tokens cascade (`inherits: true`), and the
23	// `initial-value` is the resolved depth. cssdoc reads `syntax` → Type and `initial-value` → Default.
24	const PROPERTY_RULES = STACKING_LEVELS.map((level) => {
25	  const name = `--instui-stacking-${level}`;
26	  return `@property ${name} { syntax: "<integer>"; inherits: true; initial-value: ${valueByName.get(name)}; }`;
27	}).join("\n");
28	
29	const DOC = `/**
30	 * @utility stacking
31	 * @class .instui-stack-topmost
32	 * @group Plugins
33	 * @summary z-index depth utilities: \`.instui-stack-<level>\` (\`deepest\`, \`below\`, \`above\`, \`topmost\`) set \`z-index\` from the \`--instui-stacking-*\` scale, so layers stack predictably instead of by hand-tuned numbers.
34	 * @cssproperty --instui-stacking-deepest — The lowest stacking depth.
35	 * @cssproperty --instui-stacking-below — Below the default flow.
36	 * @cssproperty --instui-stacking-above — Above the default flow.
37	 * @cssproperty --instui-stacking-topmost — The highest stacking depth (overlays, menus).
38	 * @example
39	 * <div class="instui-stack-topmost">Always on top.</div>
40	 */`;
41	
42	const sheet = `${rootCss}\n${DOC}\n${PROPERTY_RULES}\n${STACKING_RULES}\n`;
43	
44	const outDir = resolve(import.meta.dirname, "../generated");
45	mkdirSync(outDir, { recursive: true });
46	writeFileSync(join(outDir, "stacking.css"), sheet);
47	console.log(`✓ stacking: wrote stacking.css (${STACKING_RULES.split("\n").length} rules)`);
