43	 * @returns A branded {@link PantokenPlugin}.
44	 *
45	 * @example A unified tokens + css plugin
46	 * ```ts
47	 * import { capabilitiesOf, definePlugin } from "@pantoken/plugin-kit";
48	 *
49	 * const brand = definePlugin({
50	 *   name: "@acme/brand",
51	 *   tokens: (ctx) => [
52	 *     ...ctx.tokens,
53	 *     ctx.define({ name: "--instui-brand", value: "var(--instui-color-background-brand)" }),
54	 *   ],
55	 *   css: () => ({ append: ":root { color-scheme: light dark; }" }),
