95	
96	const warned = new Set<string>();
97	
98	function warnOnce(key: string, message: string): void {
99	  if (warned.has(key)) return;
100	  warned.add(key);
101	  console.warn(message);
102	}
103	
104	/**
105	 * Filter a plugin list to those that participate in `stage`, warning about the rest.
106	 *
107	 * @param plugins - The registered plugins.
108	 * @param stage - The stage being run.
109	 * @returns The plugins that have a hook for `stage`.
110	 *
111	 * @example Keep only the plugins that participate in a stage
112	 * ```ts
113	 * import { checkPlugins, definePlugin } from "@pantoken/plugin-kit";
114	 *
115	 * const tokensOnly = definePlugin({ name: "tok", tokens: (c) => c.tokens });
116	 * const cssOnly = definePlugin({ name: "styles", css: () => ({ append: "" }) });
117	 *
118	 * // Warns that "tok" has no css hook, then returns just the css plugin.
119	 * checkPlugins([tokensOnly, cssOnly], "css"); // → [cssOnly]
120	 * ```
121	 */
122	export function checkPlugins(plugins: readonly PantokenPlugin[], stage: Stage): PantokenPlugin[] {
123	  const active: PantokenPlugin[] = [];
124	  for (const plugin of plugins) {
125	    const capabilities = capabilitiesOf(plugin);
126	    if (!capabilities) {
127	      warnOnce(
128	        `${plugin.name}:${stage}:unfactoried`,
129	        `[pantoken] plugin "${plugin.name}": not created with @pantoken/plugin-kit; capability checks are skipped.`,
130	      );
131	      if (hasHook(plugin, stage)) active.push(plugin);
132	      continue;
133	    }
134	    if (!capabilities.includes(stage)) {
135	      warnOnce(
136	        `${plugin.name}:${stage}:no-hook`,
137	        `[pantoken] plugin "${plugin.name}": has no "${stage}" hook and will have no effect here; remove it from this stage.`,
138	      );
139	      continue;
140	    }
141	    active.push(plugin);
142	  }
143	  return active;
144	}
