151	function mergeContributions(a: CssContribution, b: CssContribution): CssContribution {
152	  const out: CssContribution = {};
153	  const prepend = joinCss(a.prepend, b.prepend);
154	  const append = joinCss(a.append, b.append);
155	  if (prepend) out.prepend = prepend;
156	  if (append) out.append = append;
157	  if (a.properties || b.properties)
158	    out.properties = [...(a.properties ?? []), ...(b.properties ?? [])];
159	  if (a.declarations || b.declarations)
160	    out.declarations = [...(a.declarations ?? []), ...(b.declarations ?? [])];
161	  const marker = b.marker ?? a.marker;
162	  if (marker) out.marker = marker;
