188	  const composed: PantokenPlugin = { name: overrides.name ?? base.name };
189	
190	  if (base.tokens || overrides.tokens) {
191	    composed.tokens = (ctx) => {
192	      const afterBase = base.tokens ? (base.tokens(ctx) ?? ctx.tokens) : ctx.tokens;
193	      return overrides.tokens
194	        ? (overrides.tokens({ ...ctx, tokens: afterBase }) ?? afterBase)
195	        : afterBase;
196	    };
197	  }
198	  if (base.css || overrides.css) {
199	    composed.css = (ctx) => mergeContributions(base.css?.(ctx) || {}, overrides.css?.(ctx) || {});
200	  }
201	  if (base.icons || overrides.icons) {
202	    composed.icons = (ctx) => {
203	      base.icons?.(ctx);
204	      overrides.icons?.(ctx);
205	    };
206	  }
207	  if (base.rehype || overrides.rehype) {
208	    composed.rehype = (ctx) => {
209	      const fromBase = base.rehype?.(ctx)?.resolve;
210	      const fromOverrides = overrides.rehype?.(ctx)?.resolve;
211	      const resolve: IconResolver = (code) =>
212	        fromOverrides?.(code) ?? fromBase?.(code) ?? ctx.resolve(code);
213	      return { resolve };
214	    };
215	  }
216	  if (base.native || overrides.native) {
217	    composed.native = (ctx) => {
218	      base.native?.(ctx);
219	      overrides.native?.(ctx);
220	    };
221	  }
222	  return definePlugin(composed);
223	}
