225	/**
226	 * Combine several plugins into one, folding them left-to-right with {@link extendPlugin}.
227	 *
228	 * @param plugins - The plugins to merge (at least one).
229	 * @returns A single branded plugin.
230	 *
231	 * @example Combine peer plugins into one
232	 * ```ts
233	 * import { capabilitiesOf, definePlugin, mergePlugin } from "@pantoken/plugin-kit";
234	 *
235	 * const brand = definePlugin({ name: "brand", tokens: (c) => c.tokens });
236	 * const glyphs = definePlugin({ name: "glyphs", icons: (c) => c.add({ name: "star" }) });
237	 *
238	 * const combined = mergePlugin(brand, glyphs);
239	 * capabilitiesOf(combined); // → ["tokens", "icons"]
240	 * ```
241	 */
242	export function mergePlugin(...plugins: PantokenPlugin[]): PantokenPlugin {
243	  const [first, ...rest] = plugins;
244	  if (!first) throw new Error("mergePlugin requires at least one plugin");
245	  return rest.reduce((acc, plugin) => extendPlugin(acc, plugin), first);
