1	/**
2	 * `toCss` — turn the token IR into CSS: concrete tokens become typed `@property` registrations,
3	 * themed/reference tokens become scoped declarations. Plugins can contribute or post-process CSS.
4	 *
5	 * @module
6	 */
7	import { checkPlugins } from "@pantoken/plugin-kit";
8	import { buildCssFile } from "./emit.ts";
9	import type { CssContribution, PantokenPlugin, PropertyRule, Token } from "@pantoken/model";
10	
11	/** True when a value cannot be a typed `@property` initial-value (`var()` / `light-dark()`). */
12	function isContextual(value: string): boolean {
13	  return /var\(|light-dark\(/.test(value);
14	}
15	
16	/** Options for {@link toCss}. */
17	export interface ToCssOptions {
18	  /** The selector scoped declarations are emitted under (default `":root"`). */
19	  scope?: string;
20	  /** Plugins whose `css` hooks run after the base CSS is built (default: none). */
21	  plugins?: readonly PantokenPlugin[];
22	}
23	
24	function marked(marker: string | undefined, css: string): string {
25	  return marker ? `/* ${marker} */\n${css}` : css;
26	}
27	
28	/**
29	 * Emit CSS for a token IR.
30	 *
31	 * @param tokens - The IR (e.g. from `@pantoken/tokens`).
32	 * @param options - {@link ToCssOptions}.
33	 * @returns The CSS string.
34	 *
35	 * @example Build the default stylesheet
36	 * ```ts
37	 * import { toCss } from "@pantoken/css";
38	 * import { tokens } from "@pantoken/tokens";
39	 *
40	 * const stylesheet = toCss(tokens); // declarations under :root
41	 * ```
42	 *
43	 * @example Scope declarations to a class and build another theme
44	 * ```ts
45	 * import { toCss } from "@pantoken/css";
46	 * import { byTheme } from "@pantoken/tokens";
47	 *
48	 * toCss(byTheme("canvas"), { scope: '[class*="instui"]' });
49	 * ```
50	 *
51	 * @example Post-process with a plugin css hook
52	 * ```ts
53	 * import { toCss } from "@pantoken/css";
54	 * import { tokens } from "@pantoken/tokens";
55	 *
56	 * toCss(tokens, {
57	 *   plugins: [
58	 *     {
59	 *       name: "focus",
60	 *       css: () => ({ append: ":focus-visible { outline: 2px solid var(--instui-focus-color); }" }),
61	 *     },
62	 *   ],
63	 * });
64	 * ```
65	 */
66	export function toCss(tokens: readonly Token[], options: ToCssOptions = {}): string {
67	  const { scope = ":root", plugins = [] } = options;
68	
69	  const properties: PropertyRule[] = [];
70	  const declarations: [string, string][] = [];
71	  for (const token of tokens) {
72	    if (isContextual(token.value)) declarations.push([token.name, token.value]);
73	    else properties.push({ name: token.name, syntax: token.syntax, value: token.value });
74	  }
75	
76	  let css = buildCssFile({
77	    comments: [
78	      "/* Instructure design tokens + icon set (pantoken) */",
79	      "/* Concrete tokens are registered with @property; themed/reference tokens are declarations. */",
80	    ],
81	    scope,
82	    properties,
83	    sections: [{ pairs: declarations }],
84	  });
85	
86	  const prepends: string[] = [];
87	  const appends: string[] = [];
88	  for (const plugin of checkPlugins(plugins, "css")) {
89	    const c = plugin.css?.({ tokens: tokens as Token[], css });
90	    if (!c) continue;
91	    appendContribution(c, prepends, appends);
92	  }
93	
94	  return [...prepends, css, ...appends].filter(Boolean).join("\n\n");
95	}
96	
97	function appendContribution(c: CssContribution, prepends: string[], appends: string[]): void {
98	  if (c.prepend) prepends.push(marked(c.marker, c.prepend));
99	  // A contextual initial-value (`var()`/`light-dark()`) can never be a valid `@property` registration,
100	  // so route those to declarations instead — a plugin contributing one previously emitted invalid CSS.
101	  const typedProps: PropertyRule[] = [];
102	  const declPairs: [string, string][] = [...(c.declarations ?? [])];
103	  for (const p of c.properties ?? []) {
104	    if (isContextual(p.value)) declPairs.push([p.name, p.value]);
105	    else typedProps.push(p);
106	  }
107	  const extraProps = typedProps
108	    .map(
109	      (p) =>
110	        `@property ${p.name} {\n  syntax: "${p.syntax}";\n  inherits: true;\n  initial-value: ${p.value};\n}`,
111	    )
112	    .join("\n\n");
113	  const extraDecls = declPairs.length
114	    ? `:root {\n${declPairs.map(([n, v]) => `  ${n}: ${v};`).join("\n")}\n}`
115	    : "";
116	  const block = [extraProps, extraDecls, c.append].filter(Boolean).join("\n\n");
117	  if (block) appends.push(marked(c.marker, block));
118	}
