1	import fs from "node:fs/promises";
2	import path from "node:path";
3	
4	import {
5	  BUGS_URL,
6	  ENGINES,
7	  expectedSideEffects,
8	  HOMEPAGE_URL,
9	  REPOSITORY_URL,
10	} from "./repository-metadata.ts";
11	import { isPublishablePackage, loadWorkspacePackages } from "./workspace-packages.ts";
12	
13	interface PackageManifest {
14	  repository?: unknown;
15	  homepage?: unknown;
16	  bugs?: unknown;
17	  sideEffects?: unknown;
18	  engines?: unknown;
19	  publishConfig?: unknown;
20	  license?: unknown;
21	  type?: unknown;
22	  files?: unknown;
23	  description?: unknown;
24	  exports?: unknown;
25	}
26	
27	function repositoryUrlOf(repository: unknown): string | undefined {
28	  if (typeof repository === "string") return repository;
29	  if (!repository || typeof repository !== "object") return undefined;
30	  const url = (repository as { url?: unknown }).url;
31	  return typeof url === "string" ? url : undefined;
32	}
33	
34	function repositoryDirectoryOf(repository: unknown): string | undefined {
35	  if (!repository || typeof repository !== "object") return undefined;
36	  const dir = (repository as { directory?: unknown }).directory;
37	  return typeof dir === "string" ? dir : undefined;
38	}
39	
40	const eq = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);
41	
42	async function main() {
43	  const { packages } = await loadWorkspacePackages();
44	  const publishable = packages.filter((pkg) => isPublishablePackage(pkg));
45	
46	  const violations: string[] = [];
47	
48	  for (const pkg of publishable) {
49	    const manifestPath = path.resolve(pkg.path, "package.json");
50	    const raw = await fs.readFile(manifestPath, "utf8");
51	    const m = JSON.parse(raw) as PackageManifest;
52	
53	    const fail = (msg: string): void => {
54	      violations.push(`${pkg.name} (${pkg.path}/package.json): ${msg}`);
55	    };
56	
57	    // Linkage + provenance metadata.
58	    if (repositoryUrlOf(m.repository) !== REPOSITORY_URL) {
59	      fail(
60	        `repository.url is ${JSON.stringify(repositoryUrlOf(m.repository) ?? "")}, expected ${JSON.stringify(REPOSITORY_URL)}`,
61	      );
62	    }
63	    if (repositoryDirectoryOf(m.repository) !== pkg.path) {
64	      fail(
65	        `repository.directory is ${JSON.stringify(repositoryDirectoryOf(m.repository) ?? "")}, expected ${JSON.stringify(pkg.path)}`,
66	      );
67	    }
68	    if (m.homepage !== HOMEPAGE_URL) {
69	      fail(
70	        `homepage is ${JSON.stringify(m.homepage ?? "")}, expected ${JSON.stringify(HOMEPAGE_URL)}`,
71	      );
72	    }
73	    if (m.bugs !== BUGS_URL) {
74	      fail(`bugs is ${JSON.stringify(m.bugs ?? "")}, expected ${JSON.stringify(BUGS_URL)}`);
75	    }
76	
77	    // Build-hint metadata.
78	    const wantSideEffects = expectedSideEffects(m);
79	    if (!eq(m.sideEffects, wantSideEffects)) {
80	      fail(
81	        `sideEffects is ${JSON.stringify(m.sideEffects ?? null)}, expected ${JSON.stringify(wantSideEffects)}`,
82	      );
83	    }
84	    if (!eq(m.engines, ENGINES)) {
85	      fail(`engines is ${JSON.stringify(m.engines ?? null)}, expected ${JSON.stringify(ENGINES)}`);
86	    }
87	    const provenance = (m.publishConfig as { provenance?: unknown } | undefined)?.provenance;
88	    if (provenance !== true) {
89	      fail("publishConfig.provenance is not true");
90	    }
91	
92	    // Regression insurance on the already-consistent fields.
93	    if (m.license !== "MIT") fail(`license is ${JSON.stringify(m.license ?? "")}, expected "MIT"`);
94	    if (m.type !== "module") fail(`type is ${JSON.stringify(m.type ?? "")}, expected "module"`);
95	    if (!Array.isArray(m.files) || m.files.length === 0) fail("files is missing or empty");
96	    if (typeof m.description !== "string" || m.description.length === 0) {
97	      fail("description is missing or empty");
98	    }
99	  }
100	
101	  if (violations.length > 0) {
102	    console.error("Repository metadata check failed for publishable packages:");
103	    for (const violation of violations) {
104	      console.error(`- ${violation}`);
105	    }
106	    process.exitCode = 1;
107	    return;
108	  }
109	
110	  process.stdout.write(
111	    `Repository metadata check passed for ${publishable.length} publishable packages.\n`,
112	  );
113	}
114	
115	main().catch((error) => {
116	  console.error(error instanceof Error ? error.message : String(error));
117	  process.exitCode = 1;
118	});
