40	const WORKSPACE_ROOT = path.resolve(new URL("../../", import.meta.url).pathname);
41	
42	const PACKAGE_ROOTS = [
43	  "docs",
44	  "packages",
45	  "formats",
46	  "platforms",
47	  "renderers",
48	  "bundlers",
49	  "design",
50	  "ai",
51	  "plugins/pantoken",
52	  "plugins/postcss",
53	  "plugins/typedoc",
54	  "plugins/vite",
55	  "tools",
