58	const WORKSPACE_PROTOCOL = "workspace:";
59	
60	const toPosix = (value: string): string => value.split(path.sep).join("/");
61	
62	async function listChildDirs(basePath: string): Promise<string[]> {
63	  let entries: import("node:fs").Dirent[] = [];
64	
65	  try {
66	    entries = await fs.readdir(basePath, { withFileTypes: true });
67	  } catch {
68	    return [];
69	  }
70	
71	  return entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
72	}
