74	function collectWorkspaceDeps(manifest: PackageManifest): Set<string> {
75	  const buckets = [
76	    manifest.dependencies ?? {},
77	    manifest.optionalDependencies ?? {},
78	    manifest.peerDependencies ?? {},
79	  ];
80	
81	  const deps = new Set<string>();
82	
83	  for (const bucket of buckets) {
84	    for (const [depName, depRange] of Object.entries(bucket)) {
85	      if (typeof depRange === "string" && depRange.startsWith(WORKSPACE_PROTOCOL)) {
86	        deps.add(depName);
87	      }
88	    }
89	  }
90	
91	  return deps;
92	}
