94	async function readWorkspacePackage(relDir: string): Promise<WorkspacePackage | null> {
95	  const pkgPath = path.join(WORKSPACE_ROOT, relDir, "package.json");
96	
97	  let raw;
98	  try {
99	    raw = await fs.readFile(pkgPath, "utf8");
100	  } catch {
101	    return null;
102	  }
103	
104	  let manifest: PackageManifest;
105	  try {
106	    manifest = JSON.parse(raw) as PackageManifest;
107	  } catch {
108	    throw new Error(`Invalid JSON in ${relDir}/package.json`);
109	  }
110	
111	  if (typeof manifest.name !== "string" || manifest.name.length === 0) {
112	    return null;
113	  }
