115	  return {
116	    name: manifest.name,
117	    path: relDir,
118	    version: typeof manifest.version === "string" ? manifest.version : "0.0.0",
119	    private: Boolean(manifest.private),
120	    workspaceDeps: collectWorkspaceDeps(manifest),
121	  };
