124	export async function loadWorkspacePackages(): Promise<WorkspacePackages> {
125	  const packages: WorkspacePackage[] = [];
126	  const seenPaths = new Set<string>();
127	
128	  for (const root of PACKAGE_ROOTS) {
129	    const absRoot = path.join(WORKSPACE_ROOT, root);
130	    const children = await listChildDirs(absRoot);
131	    const candidates = [root, ...children.map((child) => toPosix(path.join(root, child)))];
132	
133	    for (const relDir of candidates) {
134	      if (seenPaths.has(relDir)) {
135	        continue;
136	      }
137	      seenPaths.add(relDir);
138	
139	      const workspacePackage = await readWorkspacePackage(relDir);
140	      if (!workspacePackage) {
141	        continue;
142	      }
143	
144	      packages.push(workspacePackage);
145	    }
146	  }
147	
148	  const byName = new Map(packages.map((pkg) => [pkg.name, pkg]));
