157	export function buildReverseDependencyMap(packages: WorkspacePackage[]): Map<string, Set<string>> {
158	  const reverse = new Map<string, Set<string>>();
159	
160	  for (const pkg of packages) {
161	    if (!reverse.has(pkg.name)) {
162	      reverse.set(pkg.name, new Set());
163	    }
164	  }
165	
166	  for (const pkg of packages) {
167	    for (const dep of pkg.workspaceDeps) {
168	      if (!reverse.has(dep)) {
169	        reverse.set(dep, new Set());
170	      }
171	      const dependents = reverse.get(dep);
172	      if (dependents) {
173	        dependents.add(pkg.name);
174	      }
175	    }
176	  }
177	
178	  return reverse;
179	}
