181	export function computeReleaseSet(
182	  targetName: string,
183	  byName: Map<string, WorkspacePackage>,
184	  reverseMap: Map<string, Set<string>>,
185	): string[] {
186	  const visited = new Set<string>();
187	  const queue: string[] = [targetName];
188	
189	  while (queue.length > 0) {
190	    const current = queue.shift();
191	    if (!current) {
192	      continue;
193	    }
194	    if (visited.has(current)) {
195	      continue;
196	    }
197	
198	    visited.add(current);
199	
200	    const dependents = reverseMap.get(current);
201	    if (!dependents) {
202	      continue;
203	    }
204	
205	    for (const dependent of dependents) {
206	      if (!visited.has(dependent)) {
207	        queue.push(dependent);
208	      }
209	    }
210	  }
211	
212	  const metaPackage = byName.get("@pantoken/pantoken");
213	  const targetPackage = byName.get(targetName);
214	  if (metaPackage && targetName !== "@pantoken/pantoken" && !targetPackage?.private) {
215	    const touchesMetaSurface = [...visited].some((name) => metaPackage.workspaceDeps.has(name));
216	
217	    if (touchesMetaSurface) {
218	      visited.add(metaPackage.name);
219	    }
220	  }
221	
222	  return [...visited].sort((a, b) => a.localeCompare(b));
223	}
224	
225	export function parsePackageTag(tag: string): ParsedPackageTag | null {
226	  const match = /^(@pantoken\/[A-Za-z0-9._-]+)@v(.+)$/.exec(tag);
227	  if (!match) {
228	    return null;
229	  }
230	
231	  return {
232	    packageName: match[1],
233	    version: match[2],
234	  };
235	}
236	
237	export function normalizePantokenPackageName(value: string): string {
238	  if (!value) {
239	    return value;
240	  }
241	
242	  if (value.startsWith("@pantokens/")) {
243	    return value.replace("@pantokens/", "@pantoken/");
244	  }
245	
246	  if (value.startsWith("@pantoken/")) {
247	    return value;
248	  }
249	
250	  if (value.startsWith("@")) {
251	    return value;
252	  }
253	
254	  return `@pantoken/${value}`;
255	}
256	
257	export function parseRequestedPackageSpec(spec: string): ParsedRequestedPackageSpec {
258	  const raw = spec.trim();
259	  if (raw.length === 0) {
260	    throw new Error("Package spec cannot be empty.");
261	  }
262	
263	  const at = raw.lastIndexOf("@");
264	  const hasScopedPrefix = raw.startsWith("@");
265	
266	  // Scoped package names include one leading @ by definition.
267	  const hasVersionPart = at > 0 && (!hasScopedPrefix || at > raw.indexOf("/"));
268	
269	  if (!hasVersionPart) {
270	    return {
271	      raw,
272	      packageName: normalizePantokenPackageName(raw),
273	    };
274	  }
275	
276	  const rawName = raw.slice(0, at);
277	  const versionOrChannel = raw.slice(at + 1);
278	  if (versionOrChannel.length === 0) {
279	    throw new Error(`Invalid package spec: ${spec}`);
280	  }
281	
282	  return {
283	    raw,
284	    packageName: normalizePantokenPackageName(rawName),
285	    versionOrChannel,
286	  };
287	}
288	
289	export function isPublishablePackage(pkg: WorkspacePackage | undefined | null): boolean {
290	  if (!pkg) {
291	    return false;
292	  }
293	
294	  const candidate = pkg as WorkspacePackage;
295	
296	  return !candidate.private && candidate.name.startsWith("@pantoken/");
297	}
