31	  /\.(test|spec)\.[cm]?tsx?$/,
32	  /(^|\/)vite\.config\.[cm]?ts$/,
33	  /(^|\/)tsconfig[^/]*\.json$/,
34	  /(^|\/)cssdoc\.jsonc?$/,
