51	  for (const raw of changedFiles) {
52	    const file = toPosix(raw.trim());
53	    if (!file || NON_SHIPPED.some((re) => re.test(file))) continue;
54	    const owner = byDepth.find((pkg) => file === pkg.path || file.startsWith(`${pkg.path}/`));
55	    if (owner && isPublishablePackage(owner)) required.add(owner.name);
56	  }
57	
58	  return [...required].sort((a, b) => a.localeCompare(b));
59	}
60	
61	/** Required packages that no pending changeset will bump. Pure — no IO. */
62	export function uncoveredPackages(
63	  required: readonly string[],
64	  willBump: ReadonlySet<string>,
65	): string[] {
66	  return required.filter((name) => !willBump.has(name)).sort((a, b) => a.localeCompare(b));
67	}
68	
69	// package.json fields that never affect the published artifact consumers install, so a change confined
70	// to them warrants no release (e.g. removing a `prepublishOnly` dev script, bumping a devDependency).
71	const PACKAGE_JSON_DEV_FIELDS = ["scripts", "devDependencies"];
72	
73	/**
74	 * Does a package.json change warrant a release? True if any consumer-facing field differs — i.e. the
75	 * manifests differ once the dev-only fields ({@link PACKAGE_JSON_DEV_FIELDS}) are removed. A brand-new
76	 * manifest (`before === null`) counts as release-relevant. Pure — no IO.
77	 */
78	export function packageJsonNeedsRelease(before: unknown, after: unknown): boolean {
79	  if (before === null || before === undefined) return true;
80	  // Canonical stringify: recursively sort object keys so key-order churn isn't seen as a real change.
81	  const canonical = (v: unknown): string => {
82	    if (v === null || typeof v !== "object") return JSON.stringify(v) ?? "null";
83	    if (Array.isArray(v)) return `[${v.map(canonical).join(",")}]`;
84	    const o = v as Record<string, unknown>;
85	    return `{${Object.keys(o)
86	      .sort()
87	      .map((k) => `${JSON.stringify(k)}:${canonical(o[k])}`)
88	      .join(",")}}`;
89	  };
90	  const strip = (obj: unknown): string => {
91	    const clone = { ...(obj as Record<string, unknown>) };
92	    for (const field of PACKAGE_JSON_DEV_FIELDS) delete clone[field];
93	    return canonical(clone);
94	  };
95	  return strip(before) !== strip(after);
96	}
97	
98	function isDirectExecution(metaUrl: string): boolean {
99	  const entry = process.argv[1];
100	  return Boolean(entry) && pathToFileURL(path.resolve(entry)).href === metaUrl;
101	}
102	
103	function readArg(flag: string): string | undefined {
104	  const index = process.argv.indexOf(flag);
105	  return index >= 0 && index + 1 < process.argv.length ? process.argv[index + 1] : undefined;
106	}
107	
108	function gitDiffFiles(base: string): string[] {
109	  // Three-dot diff from the merge base, so unrelated changes already on the base don't count.
110	  const result = spawnSync("git", ["diff", "--name-only", `${base}...HEAD`], {
111	    encoding: "utf8",
112	    shell: false,
113	  });
114	  if (result.status !== 0) throw new Error(`git diff failed: ${result.stderr.trim()}`);
115	  return result.stdout.split("\n").filter(Boolean);
116	}
117	
118	/** The merge base of `base` and HEAD (the point the three-dot diff is measured from). */
119	function mergeBaseRef(base: string): string {
120	  const r = spawnSync("git", ["merge-base", base, "HEAD"], { encoding: "utf8", shell: false });
121	  return r.status === 0 ? r.stdout.trim() : base;
122	}
123	
124	/** A file's content at `ref`, or null if it didn't exist there. */
125	function gitShow(ref: string, file: string): string | null {
126	  const r = spawnSync("git", ["show", `${ref}:${file}`], { encoding: "utf8", shell: false });
127	  return r.status === 0 ? r.stdout : null;
128	}
129	
130	/**
131	 * Whether a changed file should count toward the changeset requirement. Everything counts except a
132	 * package.json whose diff only touches dev-only fields (see {@link packageJsonNeedsRelease}) — removing
133	 * a `prepublishOnly` script or bumping a devDependency doesn't change what consumers install.
134	 */
135	function releaseRelevant(file: string, ref: string): boolean {
136	  const posix = file.split(path.sep).join("/");
137	  if (posix !== "package.json" && !posix.endsWith("/package.json")) return true;
138	  const beforeRaw = gitShow(ref, posix);
139	  let before: unknown = null;
140	  if (beforeRaw !== null) {
141	    try {
142	      before = JSON.parse(beforeRaw);
143	    } catch {
144	      return true; // unparseable base → don't suppress
145	    }
146	  }
147	  let after: unknown;
148	  try {
149	    after = JSON.parse(readFileSync(posix, "utf8"));
150	  } catch {
151	    return true; // deleted or unreadable → let it count
152	  }
153	  return packageJsonNeedsRelease(before, after);
154	}
155	
156	/** Package names the pending changesets will bump, via `changeset status --output`. */
157	function willBumpPackages(base: string): Set<string> {
158	  const dir = mkdtempSync(path.join(tmpdir(), "changeset-status-"));
159	  const outFile = path.join(dir, "status.json");
160	  try {
161	    // `changeset status` exits non-zero when there are no releases; we read the JSON regardless.
162	    spawnSync("vpx", ["changeset", "status", "--since", base, "--output", outFile], {
163	      encoding: "utf8",
164	      shell: false,
165	    });
166	    let parsed: { releases?: { name: string; type: string }[] };
167	    try {
168	      parsed = JSON.parse(readFileSync(outFile, "utf8")) as typeof parsed;
169	    } catch {
170	      parsed = { releases: [] };
171	    }
172	    return new Set((parsed.releases ?? []).filter((r) => r.type !== "none").map((r) => r.name));
173	  } finally {
174	    rmSync(dir, { recursive: true, force: true });
175	  }
176	}
177	
178	async function main(): Promise<void> {
179	  const base = readArg("--base") ?? process.env.CHANGESET_BASE ?? "origin/main";
180	  const { packages } = await loadWorkspacePackages();
181	
182	  const ref = mergeBaseRef(base);
183	  const changed = gitDiffFiles(base).filter((file) => releaseRelevant(file, ref));
184	  const required = requiredPublishable(changed, packages);
185	  if (required.length === 0) {
186	    console.log("✓ changeset coverage: no publishable package needs a changeset for this diff.");
187	    return;
188	  }
189	
190	  const missing = uncoveredPackages(required, willBumpPackages(base));
191	  if (missing.length === 0) {
192	    console.log(`✓ changeset coverage: ${required.join(", ")} covered by pending changesets.`);
193	    return;
194	  }
195	
196	  console.error(
197	    "✗ changeset coverage: these publishable packages changed but no pending changeset bumps them:",
198	  );
199	  for (const name of missing) console.error(`  - ${name}`);
200	  console.error("\nAdd one with `vp run changeset:add`, then commit the file under .changeset/.");
201	  console.error(
202	    "A change that genuinely needs no release should still add a changeset bumping the package\n" +
203	      "`patch` with a note — an empty/global changeset does NOT count as coverage.",
204	  );
205	  process.exitCode = 1;
206	}
207	
208	if (isDirectExecution(import.meta.url)) {
209	  main().catch((error: unknown) => {
210	    console.error(error instanceof Error ? error.message : String(error));
211	    process.exitCode = 1;
212	  });
213	}
214

1	/**
2	 * Runtime helpers for the pantoken plugin pipeline. The plugin *contract* (types) lives in
3	 * `@pantoken/model` so emitters can depend on it without pulling the upstream token package; the
4	 * *runtime* (token-stage runner, `defineToken`) lives here.
5	 *
6	 * @module
7	 */
8	import { checkPlugins } from "@pantoken/plugin-kit";
9	import { svgToDataUri } from "./icons.ts";
10	import { cssSyntaxForValue, isContextual } from "./utils.ts";
11	import type {
12	  IconEntry,
13	  IconResolver,
14	  PantokenPlugin,
15	  Theme,
16	  Token,
17	  TokenInput,
18	} from "@pantoken/model";
19	
20	export type {
21	  CssContribution,
22	  CssHookContext,
23	  IconEntry,
24	  IconHookContext,
25	  IconResolver,
26	  PantokenPlugin,
27	  PropertyRule,
28	  RehypeHookContext,
29	  TokenHookContext,
30	} from "@pantoken/model";
31	
32	/**
33	 * Build a fully-formed {@link Token} from partial input, defaulting `inherits` and `syntax`.
34	 *
35	 * @example Sniff syntax from a concrete value
36	 * ```ts
37	 * import { defineToken } from "@pantoken/core";
38	 *
39	 * defineToken({ name: "--instui-color-x", value: "#0374B5" });
40	 * // → { name: "--instui-color-x", syntax: "<color>", inherits: true, value: "#0374B5" }
41	 * ```
42	 *
43	 * @example A single var() value records refersTo; a light-dark() sets themed
44	 * ```ts
45	 * import { defineToken } from "@pantoken/core";
46	 *
47	 * defineToken({ name: "--instui-brand", value: "var(--instui-color-background-brand)" });
48	 * // → syntax "*", refersTo: "--instui-color-background-brand"
49	 *
50	 * defineToken({ name: "--instui-bg", value: "light-dark(#fff, #000)" });
51	 * // → syntax "*", themed: true
52	 * ```
53	 */
54	export function defineToken(input: TokenInput): Token {
55	  const contextual = isContextual(input.value);
56	  const refMatch = input.value.match(/^var\((--instui-[\w-]+)\)$/);
57	  return {
58	    name: input.name,
59	    syntax: input.syntax ?? (contextual ? "*" : cssSyntaxForValue(input.value)),
60	    inherits: input.inherits ?? true,
61	    value: input.value,
62	    ...(input.themed || input.value.startsWith("light-dark(") ? { themed: true } : {}),
63	    ...((input.refersTo ?? refMatch) ? { refersTo: input.refersTo ?? refMatch?.[1] } : {}),
64	    ...(input.meta ? { meta: input.meta } : {}),
65	  };
66	}
67	
68	/**
69	 * De-duplicate tokens by name, keeping the last occurrence (so later plugins win).
70	 *
71	 * @example
72	 * ```ts
73	 * import { dedupeByName } from "@pantoken/core";
74	 * import type { Token } from "@pantoken/model";
75	 *
76	 * const tokens: Token[] = [
77	 *   { name: "--instui-x", syntax: "<color>", inherits: true, value: "#fff" },
78	 *   { name: "--instui-x", syntax: "<color>", inherits: true, value: "#000" },
79	 * ];
80	 * dedupeByName(tokens); // → one token, value "#000" (the later wins)
81	 * ```
82	 */
83	export function dedupeByName(tokens: Token[]): Token[] {
84	  const byName = new Map<string, Token>();
85	  for (const token of tokens) byName.set(token.name, token);
86	  return [...byName.values()];
87	}
88	
89	/**
90	 * Run every plugin's `tokens` hook in order. Each hook receives the current list and returns the
91	 * full replacement; the result is de-duplicated by name.
92	 *
93	 * @example
94	 * ```ts
95	 * import { runTokenPlugins, type PantokenPlugin } from "@pantoken/core";
96	 * import type { Token } from "@pantoken/model";
97	 *
98	 * const base: Token[] = [
99	 *   { name: "--instui-x", syntax: "<color>", inherits: true, value: "#fff" },
100	 * ];
101	 * const addBrand: PantokenPlugin = {
102	 *   name: "brand",
103	 *   tokens: ({ tokens, define }) => [
104	 *     ...tokens,
105	 *     define({ name: "--instui-brand", value: "#0374B5" }),
106	 *   ],
107	 * };
108	 *
109	 * runTokenPlugins(base, "rebrand", [addBrand]); // → base + the --instui-brand token
110	 * ```
111	 */
112	export function runTokenPlugins(
113	  tokens: Token[],
114	  theme: Theme,
115	  plugins: readonly PantokenPlugin[],
116	): Token[] {
117	  let acc = tokens;
118	  for (const plugin of checkPlugins(plugins, "tokens")) {
119	    const result = plugin.tokens?.({ tokens: acc, theme, define: defineToken });
120	    if (Array.isArray(result)) acc = result;
121	  }
122	  return dedupeByName(acc);
123	}
124	
125	/** Turn an {@link IconEntry} into an `<image>` icon token, or `undefined` if it has no artwork. */
126	function iconEntryToToken(entry: IconEntry): Token | undefined {
127	  const svg =
128	    entry.svg ??
129	    (entry.path
130	      ? `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${entry.viewBox ?? "0 0 24 24"}"><path d="${entry.path}"/></svg>`
131	      : undefined);
132	  if (!svg) return undefined;
133	  return defineToken({
134	    name: `--instui-icon-${entry.name}`,
135	    value: svgToDataUri(svg),
136	    syntax: "<image>",
137	    meta: { kind: "icon" },
138	  });
139	}
140	
141	/**
142	 * Run every plugin's `icons` hook, letting plugins register extra glyphs as `<image>` tokens. Each
143	 * hook gets an `add` (collects entries) and a `resolve` (looks up the current icon set). The result
144	 * is de-duplicated by name.
145	 *
146	 * @example Register an extra glyph as an <image> token
147	 * ```ts
148	 * import { runIconPlugins, type PantokenPlugin } from "@pantoken/core";
149	 * import type { Token } from "@pantoken/model";
150	 *
151	 * const base: Token[] = [];
152	 * const star: PantokenPlugin = {
153	 *   name: "star",
154	 *   icons: ({ add }) => add({ name: "star", path: "M12 2l3 7h7l-6 4 2 7-6-4-6 4 2-7-6-4h7z" }),
155	 * };
156	 *
157	 * const tokens = runIconPlugins(base, [star]);
158	 * // → adds a --instui-icon-star token whose value is a data-URI SVG
159	 * ```
160	 */
161	export function runIconPlugins(tokens: Token[], plugins: readonly PantokenPlugin[]): Token[] {
162	  const active = checkPlugins(plugins, "icons");
163	  if (active.length === 0) return tokens;
164	
165	  const added: Token[] = [];
166	  const has = (name: string): boolean =>
167	    tokens.some((t) => t.name === name) || added.some((t) => t.name === name);
168	  const resolve: IconResolver = (code) =>
169	    has(`--instui-icon-${code}`) ? { name: code } : undefined;
170	  const add = (entry: IconEntry): void => {
171	    const token = iconEntryToToken(entry);
172	    if (token) added.push(token);
173	  };
174	
175	  for (const plugin of active) plugin.icons?.({ add, resolve });
176	  return added.length ? dedupeByName([...tokens, ...added]) : tokens;
177	}
