// ── Deprecation ledger ─────────────────────────────────────────────────────────────────────────
// The token-layer analog of the inline component-modifier deprecations. When an upstream upgrade
// removes or renames a `--instui-*` token, an entry here records pantoken's policy: forward it to a
// canonical token as a compatibility shim (`"alias"`), or drop it with a migration note (`"removed"`).

/** How pantoken handles an upstream token that was removed or renamed. */
export type DeprecationPolicy = "alias" | "removed";

/** One entry in the token deprecation ledger. */
export interface DeprecationEntry {
  /** The removed/renamed upstream token name, e.g. `--instui-color-brand`. */
  token: string;
  /** The upstream ref this token disappeared in (matches the compatibility manifest). */
  since: string;
  /** `"alias"` emits a `var()` forwarder shim; `"removed"` emits nothing (migration note only). */
  policy: DeprecationPolicy;
  /** The canonical token to forward to (required for `"alias"`; a migration target for `"removed"`). */
  replacement?: string;
  /** A human note rendered in docs and the changelog. */
  note?: string;
}

/** The committed token deprecation ledger (`formats/tokens/deprecations.json`). */
export interface DeprecationLedger {
  /** The ledger schema version. */
  version: number;
  /** The deprecation entries, one per removed/renamed upstream token. */
  entries: DeprecationEntry[];
}

