/**
 * `@pantoken/plugin-deprecations` — compatibility shims for removed/renamed upstream tokens.
 *
 * When an upstream upgrade removes or renames a `--instui-*` token, a hand-authored
 * {@link DeprecationLedger} records pantoken's policy per token. This plugin reads that ledger and,
 * for every `"alias"` entry, appends a `var()` forwarder token that points at the canonical
 * replacement. Because the forwarder is a single `var(...)`, `defineToken` records its `refersTo` and
 * `toCss` emits it as a `:root` declaration — so the shim rides into css/scss/less/stylus/wordpress/
 * vanilla with no extra wiring, and inherits theming and `light-dark()` through the replacement.
 *
 * `"removed"` entries emit nothing; they surface only as migration notes in docs and the changelog.
 *
 * The intended wire-in is `@pantoken/tokens`' generate step, so the shims bake into the vendored IR
 * every downstream package reads:
 *
 * @example
 * ```ts
 * import { buildTokens } from "@pantoken/core";
 * import { deprecationShims } from "@pantoken/plugin-deprecations";
 * import ledger from "./deprecations.json" with { type: "json" };
 *
 * const tokens = buildTokens({ theme: "rebrand", plugins: [deprecationShims(ledger)] });
 * // → adds e.g. --instui-color-brand: var(--instui-color-background-brand)
 * ```
 *
 * @module
 * @beta
 */
import { definePlugin } from "@pantoken/plugin-kit";
import type { DeprecationEntry, DeprecationLedger, PantokenPlugin } from "@pantoken/model";

/** The `"alias"` entries that emit a shim (a `replacement` is required, so incomplete ones are dropped). */
export function aliasEntries(ledger: DeprecationLedger): DeprecationEntry[] {
  return ledger.entries.filter((e) => e.policy === "alias" && Boolean(e.replacement));
}

/** True when the ledger records a policy (alias or removed) for `token`. */
export function ledgerCovers(ledger: DeprecationLedger, token: string): boolean {
  return ledger.entries.some((e) => e.token === token);
}

/**
 * Create the deprecation-shim plugin from a ledger.
 *
 * @param ledger - The {@link DeprecationLedger} (e.g. `formats/tokens/deprecations.json`).
 * @returns A {@link PantokenPlugin} whose `tokens` hook appends one `var()` forwarder per alias entry.
 */
export function deprecationShims(ledger: DeprecationLedger): PantokenPlugin {
  const aliases = aliasEntries(ledger);
  return definePlugin({
    name: "@pantoken/plugin-deprecations",
    tokens: ({ tokens, define }) => [
      ...tokens,
      ...aliases.map((e) =>
        define({
          name: e.token,
          value: `var(${e.replacement})`,
          meta: {
            deprecated: {
              replacement: e.replacement,
              since: e.since,
              ...(e.note ? { note: e.note } : {}),
            },
          },
        }),
      ),
    ],
  });
}

export default deprecationShims;

import { expect, test } from "vite-plus/test";
import { capabilitiesOf } from "@pantoken/plugin-kit";
import { aliasEntries, deprecationShims, ledgerCovers } from "../src/index.ts";
import type { DeprecationLedger, Token } from "@pantoken/model";

const define = (i: { name: string; value: string; meta?: Token["meta"] }): Token => ({
  name: i.name,
  syntax: i.value.includes("var(") ? "*" : "<color>",
  inherits: true,
  value: i.value,
  ...(i.value.startsWith("var(") ? { refersTo: i.value.slice(4, -1) } : {}),
  ...(i.meta ? { meta: i.meta } : {}),
});

const ledger: DeprecationLedger = {
  version: 1,
  entries: [
    {
      token: "--instui-color-brand",
      since: "v1.5.0",
      policy: "alias",
      replacement: "--instui-color-background-brand",
      note: "Renamed upstream.",
    },
    { token: "--instui-legacy-gone", since: "v1.5.0", policy: "removed", note: "Migrate away." },
    // An incomplete alias (no replacement) is ignored rather than emitting a broken shim.
    { token: "--instui-color-oops", since: "v1.5.0", policy: "alias" },
  ],
};

test("is a factoried tokens-only plugin", () => {
  expect(capabilitiesOf(deprecationShims(ledger))).toEqual(["tokens"]);
});

test("aliasEntries keeps only alias entries that have a replacement", () => {
  expect(aliasEntries(ledger).map((e) => e.token)).toEqual(["--instui-color-brand"]);
});

test("ledgerCovers reports whether a token has any policy", () => {
  expect(ledgerCovers(ledger, "--instui-legacy-gone")).toBe(true);
  expect(ledgerCovers(ledger, "--instui-not-listed")).toBe(false);
});

test("tokens hook appends a var() forwarder for each alias, carrying meta.deprecated", () => {
  const out = deprecationShims(ledger).tokens?.({ tokens: [], theme: "rebrand", define }) ?? [];
  const shim = out.find((t) => t.name === "--instui-color-brand");
  expect(shim?.value).toBe("var(--instui-color-background-brand)");
  expect(shim?.refersTo).toBe("--instui-color-background-brand");
  expect(shim?.meta?.deprecated?.since).toBe("v1.5.0");
  // `removed` and incomplete-alias entries emit nothing.
  expect(out.some((t) => t.name === "--instui-legacy-gone")).toBe(false);
  expect(out.some((t) => t.name === "--instui-color-oops")).toBe(false);
});

