/**
 * The upstream-drift runner. Builds a manifest from the live `@pantoken/tokens` build, diffs it
 * against the committed baseline, and either fails (unblessed drift) or blesses a new baseline.
 *
 * Usage (via the vp task DAG):
 * - `vp run upgrade:check`  — diff current vs baseline; write the report; exit non-zero if they differ.
 * - `vp run upgrade:bless`  — rewrite the baseline from the current build (accept a reviewed bump).
 *
 * The gate is a lockfile-style invariant: the committed baseline must match the current build, so a PR
 * that bumps the upstream pin has to bless the baseline in the same change. That surfaces every token
 * and icon delta in the PR diff and in the printed report.
 *
 * @module
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { provenance } from "@pantoken/tokens/meta";
import { themes } from "@pantoken/tokens";
import {
  buildManifest,
  diffManifests,
  manifestsEqual,
  serializeManifest,
  toJsonReport,
  toMarkdownReport,
  type Manifest,
} from "./lib.ts";

const here = import.meta.dirname;
const baselinePath = resolve(here, "baseline/manifest.json");
const reportDir = resolve(here, "generated");

const bless = process.argv.includes("--bless");

const current = buildManifest({ themes, provenance });

if (bless) {
  mkdirSync(resolve(here, "baseline"), { recursive: true });
  writeFileSync(baselinePath, serializeManifest(current));
  console.log(
    `✓ blessed baseline: design-tokens ${provenance.designTokens.ref}@${provenance.designTokens.commit.slice(0, 7)}, ui-icons ${provenance.uiIcons.resolved}`,
  );
  process.exit(0);
}

if (!existsSync(baselinePath)) {
  console.error(
    "✗ upstream-diff: no baseline at baseline/manifest.json. Bootstrap it with `vp run upgrade:bless`.",
  );
  process.exit(1);
}

const baseline = JSON.parse(readFileSync(baselinePath, "utf8")) as Manifest;
const diff = diffManifests(baseline, current);

mkdirSync(reportDir, { recursive: true });
writeFileSync(join(reportDir, "report.json"), toJsonReport(diff));
const markdown = toMarkdownReport(diff);
writeFileSync(join(reportDir, "report.md"), `${markdown}\n`);
console.log(markdown);

if (!manifestsEqual(baseline, current)) {
  console.error(
    "\n✗ upstream-diff: the committed baseline is stale. Review the drift above, then run `vp run upgrade:bless` and commit tools/upstream-diff/baseline/manifest.json in this change.",
  );
  process.exit(1);
}

console.log("\n✓ upstream-diff: baseline matches the current build (no unblessed drift).");

{
  "name": "@pantoken/upstream-diff",
  "version": "0.1.0",
  "private": true,
  "description": "Upstream-drift gate: project the built token IR into a compact committed manifest and classify what an Instructure UI bump changed (added/removed/renamed/retyped tokens and icons) into review buckets.",
  "license": "MIT",
  "type": "module",
  "scripts": {
    "diff": "node index.ts",
    "bless": "node index.ts --bless",
    "test": "vp test",
    "check": "vp check"
  },
  "dependencies": {
    "@pantoken/tokens": "workspace:*"
  },
  "devDependencies": {
    "@types/node": "catalog:",
    "typescript": "catalog:",
    "vite": "catalog:",
    "vite-plus": "catalog:"
  }
}

import { expect, test } from "vite-plus/test";
import {
  buildManifest,
  categoryOf,
  diffManifests,
  manifestsEqual,
  type Manifest,
} from "./lib.ts";
import type { Provenance } from "@pantoken/tokens/meta";
import type { Token } from "@pantoken/tokens";

const prov = (ref: string, icons: string): Provenance => ({
  designTokens: { package: "@instructure/instructure-design-tokens", ref, commit: "abcdef0" },
  uiIcons: { package: "@instructure/ui-icons", resolved: icons },
});

const tok = (name: string, value: string, extra: Partial<Token> = {}): Token => ({
  name,
  syntax: value.startsWith("#") ? "<color>" : value.includes("var(") ? "*" : "<length>",
  inherits: true,
  value,
  ...extra,
});

const icon = (name: string, value: string, meta: Token["meta"] = {}): Token => ({
  name,
  syntax: "<image>",
  inherits: false,
  value,
  meta: { kind: "icon", ...meta },
});

function manifest(ref: string, tokens: Token[]): Manifest {
  return buildManifest({
    themes: { rebrand: tokens, canvas: tokens, canvasHighContrast: tokens },
    provenance: prov(ref, "11.7.3"),
  });
}

test("categoryOf routes syntax to a value family", () => {
  expect(categoryOf("<color>")).toBe("color");
  expect(categoryOf("<length>")).toBe("length");
  expect(categoryOf("<integer>")).toBe("number");
  expect(categoryOf("<image>")).toBe("image");
  expect(categoryOf("*")).toBe("other");
});

test("buildManifest stores icons once (theme-independent) and tokens per theme", () => {
  const m = manifest("v1.4.0", [
    tok("--instui-color-x", "#0374B5"),
    icon("--instui-icon-star", "data:image/svg+xml,STAR"),
  ]);
  expect(Object.keys(m.icons)).toEqual(["--instui-icon-star"]);
  expect(m.themes.rebrand["--instui-color-x"].value).toBe("#0374B5");
  // The icon's fat value is stored as a hash, not verbatim.
  expect(m.icons["--instui-icon-star"].hash).not.toContain("data:");
});

test("diff classifies added, removed, value, and ref changes", () => {
  const before = manifest("v1.4.0", [
    tok("--instui-color-keep", "#111111"),
    tok("--instui-color-gone", "#222222"),
    tok("--instui-ref", "var(--instui-color-a)", { syntax: "*", refersTo: "--instui-color-a" }),
  ]);
  const after = manifest("v1.5.0", [
    tok("--instui-color-keep", "#999999"),
    tok("--instui-color-new", "#333333"),
    tok("--instui-ref", "var(--instui-color-b)", { syntax: "*", refersTo: "--instui-color-b" }),
  ]);
  const diff = diffManifests(before, after);
  expect(diff.buckets.addedTokens.map((c) => c.name)).toContain("--instui-color-new");
  expect(diff.buckets.removedTokens.map((c) => c.name)).toContain("--instui-color-gone");
  // The value change appears per theme (3), coloured.
  const valueNames = diff.buckets.valueChanges.filter((c) => c.name === "--instui-color-keep");
  expect(valueNames.length).toBe(3);
  expect(valueNames[0].category).toBe("color");
  expect(diff.buckets.refChanges[0].name).toBe("--instui-ref");
  // Removed tokens land in the manual-review subset.
  expect(diff.manualReview.some((c) => c.name === "--instui-color-gone")).toBe(true);
});

test("diff detects an icon rename by matching artwork hash", () => {
  const before = manifest("v1.4.0", [icon("--instui-icon-old-name", "data:image/svg+xml,ART")]);
  const after = manifest("v1.5.0", [icon("--instui-icon-new-name", "data:image/svg+xml,ART")]);
  const diff = diffManifests(before, after);
  expect(diff.buckets.renamedIcons).toEqual([
    { name: "--instui-icon-old-name", kind: "icon-renamed", renamedTo: "--instui-icon-new-name" },
  ]);
  expect(diff.buckets.removedIcons).toEqual([]);
  expect(diff.buckets.addedIcons).toEqual([]);
});

test("identical builds produce no drift and compare equal", () => {
  const a = manifest("v1.4.0", [tok("--instui-color-x", "#0374B5")]);
  const b = manifest("v1.4.0", [tok("--instui-color-x", "#0374B5")]);
  expect(manifestsEqual(a, b)).toBe(true);
  expect(diffManifests(a, b).summary.total).toBe(0);
});

import { defineConfig } from "vite-plus";

export default defineConfig({
  lint: {
    options: {
      typeAware: true,
      typeCheck: true,
    },
  },
  fmt: {},
});

/**
 * Build the pantoken compatibility manifest: which upstream Instructure UI sources this build resolves
 * from, and which consumers are validated against it. Pure-ish (reads repo files, no network), so the
 * writer (`generate-compatibility.ts`) and the gate (`check-compatibility.ts`) share one source of
 * truth and can't drift.
 *
 * Two upstream tiers, because pantoken consumes Instructure UI two different ways:
 * - `token-ir` / `icons` — the GitHub-only design-tokens source and `@instructure/ui-icons` feed the
 *   resolved token IR that every format, platform, and renderer consumes.
 * - `instui-react` — the eight `@instructure/ui-*` React packages, consumed *only* by
 *   `renderers/react-markdown`, which renders real InstUI components.
 *
 * @module
 */
import fs from "node:fs/promises";
import path from "node:path";
import { loadWorkspacePackages } from "./workspace-packages.ts";

const WORKSPACE_ROOT = path.resolve(new URL("../../", import.meta.url).pathname);

const TOKEN_SOURCE = "@instructure/instructure-design-tokens";
const ICON_SOURCE = "@instructure/ui-icons";
/** The InstUI React packages, consumed only by `renderers/react-markdown`. */
const REACT_PACKAGES = [
  "@instructure/ui-heading",
  "@instructure/ui-text",
  "@instructure/ui-link",
  "@instructure/ui-list",
  "@instructure/ui-table",
  "@instructure/ui-view",
  "@instructure/ui-img",
  "@instructure/ui-alerts",
];

/** Which pantoken layer an upstream package feeds. */
export type Feeds = "token-ir" | "icons" | "instui-react";

/** One upstream dependency's support record. */
export interface UpstreamEntry {
  /** The version range as pinned in the catalog. */
  range: string;
  /** The concrete resolved version/ref this build vendored. */
  resolved: string;
  /** The pantoken layer this source feeds. */
  feeds: Feeds;
}

/** One consumer package's support record. */
export interface ConsumerEntry {
  package: string;
  path: string;
  /** The upstream tier that governs this consumer. */
  governedBy: "token-ir" | "instui-react";
}

/** The full compatibility manifest (`compatibility.json`). */
export interface Compatibility {
  upstream: Record<string, UpstreamEntry>;
  consumers: ConsumerEntry[];
}

/** Provenance written by `@pantoken/tokens`' generate step. */
interface Meta {
  designTokens: { package: string; ref: string; commit: string };
  uiIcons: { package: string; resolved: string };
}

/** The `#ref`-and-value a package is pinned to in the catalog. */
function catalogRange(workspaceYaml: string, pkg: string): string {
  const line = workspaceYaml
    .split("\n")
    .find((l) => l.includes(`"${pkg}":`) || l.trimStart().startsWith(`${pkg}:`));
  if (!line) return "unknown";
  const value = line.slice(line.indexOf(":", line.indexOf(pkg)) + 1).trim();
  return value.replace(/^["']|["']$/gu, "");
}

/** The concrete version a semver-pinned package resolved to, from the lockfile. */
function lockResolved(lockfile: string, pkg: string): string {
  const match = lockfile.match(new RegExp(`'${pkg.replace(/[/@]/gu, (c) => c)}@([^']+)':`, "u"));
  return match?.[1] ?? "unknown";
}

/** Read a package's `@instructure/*` runtime/peer dependency names. */
async function instuiDeps(pkgPath: string): Promise<string[]> {
  try {
    const raw = await fs.readFile(path.join(WORKSPACE_ROOT, pkgPath, "package.json"), "utf8");
    const m = JSON.parse(raw) as {
      dependencies?: Record<string, string>;
      peerDependencies?: Record<string, string>;
    };
    return [...Object.keys(m.dependencies ?? {}), ...Object.keys(m.peerDependencies ?? {})].filter(
      (name) => name.startsWith("@instructure/"),
    );
  } catch {
    return [];
  }
}

/**
 * Build the compatibility manifest from the repo's current state (catalog, lockfile, vendored
 * provenance, and the workspace packages).
 *
 * @returns The {@link Compatibility} manifest — deterministic, no timestamps, so the gate can diff it.
 */
export async function buildCompatibility(): Promise<Compatibility> {
  const [workspaceYaml, lockfile, metaRaw] = await Promise.all([
    fs.readFile(path.join(WORKSPACE_ROOT, "pnpm-workspace.yaml"), "utf8"),
    fs.readFile(path.join(WORKSPACE_ROOT, "pnpm-lock.yaml"), "utf8"),
    fs.readFile(
      path.join(WORKSPACE_ROOT, "formats/tokens/generated/meta.json"),
      "utf8",
    ),
  ]);
  const meta = JSON.parse(metaRaw) as Meta;

  const upstream: Record<string, UpstreamEntry> = {
    [TOKEN_SOURCE]: {
      range: catalogRange(workspaceYaml, TOKEN_SOURCE),
      resolved: `${meta.designTokens.ref}@${meta.designTokens.commit.slice(0, 12)}`,
      feeds: "token-ir",
    },
    [ICON_SOURCE]: {
      range: catalogRange(workspaceYaml, ICON_SOURCE),
      resolved: meta.uiIcons.resolved,
      feeds: "icons",
    },
  };
  for (const pkg of REACT_PACKAGES) {
    upstream[pkg] = {
      range: catalogRange(workspaceYaml, pkg),
      resolved: lockResolved(lockfile, pkg),
      feeds: "instui-react",
    };
  }

  const { packages } = await loadWorkspacePackages();
  const consumerPkgs = packages.filter(
    (p) => p.path.startsWith("renderers/") || p.path.startsWith("platforms/"),
  );
  const consumers: ConsumerEntry[] = [];
  for (const pkg of consumerPkgs) {
    const deps = await instuiDeps(pkg.path);
    const usesReact = deps.some((d) => REACT_PACKAGES.includes(d));
    consumers.push({ package: pkg.name, path: pkg.path, governedBy: usesReact ? "instui-react" : "token-ir" });
  }
  consumers.sort((a, b) => a.path.localeCompare(b.path));

  return { upstream, consumers };
}

/** Render the manifest as a human support-matrix Markdown page. */
export function renderMarkdown(compat: Compatibility): string {
  const upstreamRows = Object.entries(compat.upstream)
    .map(([name, e]) => `| \`${name}\` | ${e.feeds} | \`${e.range}\` | \`${e.resolved}\` |`)
    .join("\n");
  const consumerRows = compat.consumers
    .map((c) => `| \`${c.package}\` | \`${c.path}\` | ${c.governedBy} |`)
    .join("\n");

  return `# Compatibility

<!-- Generated by \`vp run sync:compatibility\`. Do not edit by hand; run the writer and commit. -->

This page records the Instructure UI sources this pantoken build resolves from, and which consumers
are validated against it. Regenerate it with \`vp run sync:compatibility\`; the \`gate:compatibility\`
check fails if it drifts.

## Upstream sources

pantoken consumes Instructure UI two ways: the design tokens and icons feed the resolved token IR that
every package consumes, while the \`@instructure/ui-*\` React packages are used only by
\`@pantoken/react-markdown\`.

| Package | Feeds | Range | Resolved |
| --- | --- | --- | --- |
${upstreamRows}

## Consumers

| Package | Path | Governed by |
| --- | --- | --- |
${consumerRows}
`;
}

/**
 * Writer for the compatibility manifest. Regenerates `compatibility.json` (the machine-readable
 * source of truth) and `docs/compatibility.md` (its human support-matrix render) from the repo's
 * current catalog, lockfile, vendored provenance, and workspace packages. Run after an upstream bump
 * or after adding a consumer; the `gate:compatibility` check then keeps it correct.
 *
 * @module
 */
import fs from "node:fs/promises";
import path from "node:path";
import { buildCompatibility, renderMarkdown } from "./compatibility.ts";

const ROOT = path.resolve(new URL("../../", import.meta.url).pathname);

async function main(): Promise<void> {
  const compat = await buildCompatibility();
  await fs.writeFile(
    path.join(ROOT, "compatibility.json"),
    `${JSON.stringify(compat, null, 2)}\n`,
  );
  await fs.writeFile(path.join(ROOT, "docs/compatibility.md"), renderMarkdown(compat));
  console.log(
    `✓ compatibility: wrote compatibility.json + docs/compatibility.md (${Object.keys(compat.upstream).length} upstream sources, ${compat.consumers.length} consumers)`,
  );
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});

/**
 * Gate for the compatibility manifest. Rebuilds the expected manifest in memory and fails if the
 * committed `compatibility.json` doesn't match — so an upstream bump or a new consumer must
 * regenerate it (`vp run sync:compatibility`) in the same change. Compares the *parsed* objects, so
 * it never fights the JSON formatter over whitespace.
 *
 * @module
 */
import fs from "node:fs/promises";
import path from "node:path";
import { buildCompatibility, type Compatibility } from "./compatibility.ts";

const ROOT = path.resolve(new URL("../../", import.meta.url).pathname);

/** Canonical (key-sorted) JSON, so equality ignores key order and whitespace. */
function canonical(value: unknown): string {
  const sort = (v: unknown): unknown => {
    if (v === null || typeof v !== "object") return v;
    if (Array.isArray(v)) return v.map(sort);
    const o = v as Record<string, unknown>;
    return Object.fromEntries(Object.keys(o).sort().map((k) => [k, sort(o[k])]));
  };
  return JSON.stringify(sort(value));
}

async function main(): Promise<void> {
  const expected = await buildCompatibility();

  let committed: Compatibility | null = null;
  try {
    committed = JSON.parse(await fs.readFile(path.join(ROOT, "compatibility.json"), "utf8")) as Compatibility;
  } catch {
    committed = null;
  }

  if (!committed) {
    console.error(
      "✗ compatibility: compatibility.json is missing or unparseable. Run `vp run sync:compatibility` and commit it.",
    );
    process.exitCode = 1;
    return;
  }

  if (canonical(committed) !== canonical(expected)) {
    console.error(
      "✗ compatibility: compatibility.json is stale (upstream pins or consumers changed).",
    );
    console.error("  Run `vp run sync:compatibility` and commit compatibility.json + docs/compatibility.md.");
    process.exitCode = 1;
    return;
  }

  console.log(
    `✓ compatibility: manifest matches (${Object.keys(expected.upstream).length} upstream sources, ${expected.consumers.length} consumers).`,
  );
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
