1	/**
2	 * The upstream-drift runner. Builds a manifest from the live `@pantoken/tokens` build, diffs it
3	 * against the committed baseline, and either fails (unblessed drift) or blesses a new baseline.
4	 *
5	 * Usage (via the vp task DAG):
6	 * - `vp run upgrade:check`  — diff current vs baseline; write the report; exit non-zero if they differ.
7	 * - `vp run upgrade:bless`  — rewrite the baseline from the current build (accept a reviewed bump).
8	 *
9	 * The gate is a lockfile-style invariant: the committed baseline must match the current build, so a PR
10	 * that bumps the upstream pin has to bless the baseline in the same change. That surfaces every token
11	 * and icon delta in the PR diff and in the printed report.
12	 *
13	 * @module
14	 */
15	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
16	import { join, resolve } from "node:path";
17	import { provenance } from "@pantoken/tokens/meta";
18	import { themes } from "@pantoken/tokens";
19	import { ledgerCovers } from "@pantoken/plugin-deprecations";
20	import type { DeprecationLedger } from "@pantoken/model";
21	import {
22	  buildManifest,
